
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_opwlyp_d_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_opwlyp_d", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.380079759192055e+00, -4.298108306200589e+00, -4.183318405595553e+00, -4.024456072213309e+00, -3.808298533375686e+00, -3.521252082753223e+00, -3.153078345868102e+00, -2.703450639651962e+00, -2.190066880649064e+00, -1.649624774375575e+00, -1.113664587206537e+00, -7.423895572502607e-01, -6.380371395467359e-01, -5.321361099404738e-01, -3.882848646918647e-01, -2.456334482995426e-01, -1.447110967338153e-01, -9.611874067432559e-02, -6.104428503185317e-02, -4.171905181246607e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


